    "text": "A person earns a monthly income of ₹80,000. If they save \\(15\\%\\) of their income every month, what is their monthly expenditure?",
    "options": [
      {
        "text": "₹12,000",
        "isCorrect": false
      },
      {
        "text": "₹70,000",
        "isCorrect": false
      },
      {
        "text": "₹66,000",
        "isCorrect": false
      },
      {
        "text": "₹68,000",
        "isCorrect": true
      }
    ],
    "correctAnswer": "D",
    "solution": "Step 1: Formula connecting income, expenditure, and savings: \\(\\text{Income} = \\text{Expenditure} + \\text{Savings}\\).\nStep 2: Savings = \\(15\\%\\) of ₹80,000 = \\(\\frac{15}{100} \\times 80000 = \\text{₹}12,000\\).\nStep 3: Expenditure = \\(\\text{Income} - \\text{Savings} = 80000 - 12000 = \\text{₹}68,000\\).",
    "boardCode": "MH",
    "board": "Maharashtra Board",
    "class": "9",
    "subjectCode": "MTH1",
    "subject": "Mathematics Part - 1 (Algebra)",
    "chapterNumber": 6,
    "chapter": "Financial Planning",
    "topicCode": "MH-9-MTH1-6-6.1.1",
    "topic": "Importance of savings",
    "type": "OSC",
